<?php require_once '../../includes/auth.php';require_once '../../config/conexion.php';exigir_roles(['Administrador del sistema']);$titulo='Bitácora de cambios';require '../../includes/header.php';$rows=$pdo->query("SELECT b.fecha_hora,u.usuario,b.tabla_afectada,b.id_registro,b.accion FROM bitacora_cambios b JOIN usuarios u ON u.id_usuario=b.id_usuario ORDER BY b.id_bitacora DESC LIMIT 200")->fetchAll();?><h1>Bitácora de cambios</h1><div class="panel tabla-wrap"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Tabla</th><th>Registro</th><th>Acción</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['fecha_hora']) ?></td><td><?= h($r['usuario']) ?></td><td><?= h($r['tabla_afectada']) ?></td><td><?= h($r['id_registro']) ?></td><td><?= h($r['accion']) ?></td></tr><?php endforeach;?></tbody></table></div><?php require '../../includes/footer.php';?>